diff --git i/internal/ui/datatable/render.go w/internal/ui/datatable/render.go
index 72a32d2a..cc3dfbe2 100644
--- i/internal/ui/datatable/render.go
+++ w/internal/ui/datatable/render.go
@@ -5,6 +5,7 @@ import (

 	"charm.land/bubbles/v2/table"
 	"charm.land/lipgloss/v2"
+	"github.com/charmbracelet/x/ansi"
 	"github.com/mattn/go-runewidth"

 	"github.com/anthnel/devdesk/internal/ui/indicator"
@@ -195,14 +196,68 @@ func (m *Model[T]) indicatorCellStyle(state indicator.State, selected bool) lipg

 // fit truncates the text to the column and pads it out, emitting no escape
 // sequence of its own — the caller styles what comes back. Doing it in that
-// order is the whole point of this file: runewidth counts an escape sequence's
-// bytes as width, so text has to be measured while it is still plain.
+// order is the whole point of this file: an escape sequence's bytes would count
+// as width, so text has to be measured while it is still plain.
+//
+// Measuring, cutting and padding all go by grapheme clusters, the primitive
+// x/ansi sums in StringWidth, so a cell is exactly as wide as Lip Gloss and the
+// viewport think it is, VS16 emoji and keycaps included (DEVDESK-280).
 func fit(text string, width int, head bool) string {
-	cut := runewidth.Truncate(text, width, truncationMarker)
+	if width <= 0 {
+		return ""
+	}
+	cut := truncateTail(text, width)
 	if head {
 		cut = truncateHead(text, width)
 	}
-	return lipgloss.NewStyle().Width(width).MaxWidth(width).Inline(true).Render(cut)
+	if pad := width - cellWidth(cut); pad > 0 {
+		cut += strings.Repeat(" ", pad)
+	}
+	return cut
+}
+
+// cellWidth is the width of text in terminal cells, summed per grapheme
+// cluster. It equals ansi.StringWidth for any input.
+func cellWidth(text string) int {
+	total := 0
+	for len(text) > 0 {
+		cluster, w := ansi.FirstGraphemeCluster(text, ansi.GraphemeWidth)
+		if cluster == "" {
+			break
+		}
+		total += w
+		text = text[len(cluster):]
+	}
+	return total
+}
+
+// truncateTail keeps the start of text, ending it with the marker when
+// something is cut. It never splits a grapheme cluster, and the result is never
+// wider than width.
+func truncateTail(text string, width int) string {
+	if width <= 0 {
+		return ""
+	}
+	if cellWidth(text) <= width {
+		return text
+	}
+	marker := cellWidth(truncationMarker)
+	if width < marker {
+		return ""
+	}
+	budget := width - marker
+	var b strings.Builder
+	used := 0
+	for rest := text; rest != ""; {
+		cluster, w := ansi.FirstGraphemeCluster(rest, ansi.GraphemeWidth)
+		if cluster == "" || used+w > budget {
+			break
+		}
+		b.WriteString(cluster)
+		used += w
+		rest = rest[len(cluster):]
+	}
+	return b.String() + truncationMarker
 }

 // truncateHead keeps the *end* of the text, for the columns that declare it
@@ -213,20 +268,33 @@ func fit(text string, width int, head bool) string {
 // and it does so precisely when the column is squeezed to its floor, which is
 // when it is hardest to read. Keeping the end is what tells the rows apart.
 //
-// runewidth rather than runes throughout: a cell is measured in terminal cells,
-// and a CJK name counts two per rune.
+// Cells rather than runes throughout: a cell is measured in terminal cells,
+// and a CJK name counts two per rune. The cut falls on a cluster boundary.
 func truncateHead(text string, width int) string {
-	total := runewidth.StringWidth(text)
-	if total <= width || width <= 0 {
+	if width <= 0 || cellWidth(text) <= width {
 		return text
 	}
-	marker := runewidth.StringWidth(truncationMarker)
+	marker := cellWidth(truncationMarker)
 	if width <= marker {
 		// No room for the marker and anything after it. Saying "there is more"
 		// with no idea what beats a single arbitrary character.
-		return runewidth.Truncate(truncationMarker, width, "")
+		return truncateTail(truncationMarker, width)
 	}
-	return runewidth.TruncateLeft(text, total-(width-marker), truncationMarker)
+	// Drop clusters from the front until the rest fits next to the marker.
+	skip := cellWidth(text) - (width - marker)
+	dropped := 0
+	for text != "" && dropped < skip {
+		cluster, w := ansi.FirstGraphemeCluster(text, ansi.GraphemeWidth)
+		if cluster == "" {
+			break
+		}
+		dropped += w
+		text = text[len(cluster):]
+	}
+	// A wide cluster straddling the cut leaves a hole: it sits after the marker,
+	// so the kept end stays flush right.
+	hole := width - marker - cellWidth(text)
+	return truncationMarker + strings.Repeat(" ", max(hole, 0)) + text
 }

 // cellStyle is the style one cell is rendered with.
317:### Step 3 — move the library pins where runewidth still lives (S; after step 1, parallel with step 2)
318-
319-- **Move** `TestDatatableWidthAgreesWithTheGraphemeWidth` and its `agreedWidths` table to
320-  `internal/ui/theme/text_test.go` as **`TestThemeStringWidthAgreesWithTheGraphemeWidth`**,
321-  asserting `theme.StringWidth(s) == ansi.StringWidth(s)`. Its subject is now the theme
322-  helpers (the remaining runewidth users). Keep the "Red proof" comment.
323-  Add `"\U000F0219"` (a Nerd Font Material glyph, supplementary PUA) to the table as a guard for
324-  the newer Nerd Font range.
325-- **Add** `TestThemeStringWidthVS16IsAKnownDivergence` in the same file: pins
326-  `theme.StringWidth("✔️") == 1`, `ansi.StringWidth("✔️") == 2` (and `a❤️x` 3 vs 4), with the
327-  comment that it is the cue for the follow-up story (§9) and that the table no longer shares
328-  it.
329-- **Rewrite** `TestRunewidthMisreadsStyledTextWhichIsWhyCellIsPlain` (`render_test.go:377`) as
330-  **`TestTheTableCutMisreadsStyledTextWhichIsWhyCellIsPlain`**: same styled `"running"`,
331-  asserting `cellWidth(styled) > lipgloss.Width(styled)` and
332-  `truncateTail(styled, 12) != styled`. The premise survives because the cluster walk, like
333-  runewidth, reads an escape sequence as text (§4); only the library named changes. After
334-  this, nothing in `datatable` tests imports `go-runewidth` except
335-  `indicator_eastasian_test.go`.
336-
337-**Run:** `go test ./internal/ui/theme ./internal/ui/datatable -count=1`.
338-**Done when:** green; `grep -rn go-runewidth internal/ui/datatable` lists only
339-`render.go` (FillRight) and `indicator_eastasian_test.go`.
340-
341-### Step 4 — documentation (S; after steps 1–3, parallel with nothing)
342-
343-| File | Change |
344-|---|---|
345-| `.claude/rules/tui-tables.md`, Rule 116 "Which width library measures what" | The datatable now measures, cuts and pads with `x/ansi` like Lip Gloss and the viewport; one exception, the indicator cell (`runewidth.FillRight`, East Asian ambiguous, a single-rune glyph). Remove "Do not put a VS16 emoji in a table cell" and the known-divergence sentence; name `TestDatatableMeasuresVS16LikeAnsi`, `TestDatatableMeasuresWithOneLibrary`. Keep: on a terminal without mode 2027 the *renderer* counts VS16 as 1 (D117). |
346-| `.claude/rules/tui-tables.md`, Rule 122 "Why" | Replace "the measurement goes through `runewidth`, which counts an escape sequence's bytes as width" by "the table's cut walks grapheme clusters and, like runewidth, counts an escape sequence's bytes as width" (true by design, §4); name `TestTheTableCutMisreadsStyledTextWhichIsWhyCellIsPlain`. The bubbles history and the rule itself do not change (H2). |
347-| `docs/architecture/ui-components.md` l.285-294 and l.302-304 | Same correction: the table cuts and pads by grapheme clusters, the width x/ansi gives Lip Gloss and the viewport; the VS16 divergence is gone from the table and lives in the theme helpers (`TestThemeStringWidthVS16IsAKnownDivergence`); why not `ansi.Truncate` (keycaps). l.561-568 (indicator `FillRight`) stays, add "the only runewidth call left in the package". Add a short "Cost" line: printable-ASCII fast path, `BenchmarkView`. Same for l.95-99 only if it speaks of the table (it speaks of the footer: unchanged). |

